import sys


def escape_html(text):
    """Return text safe to put inside HTML: ampersand, less-than, greater-than and both quote marks become entities."""
    # & first: replacing it later would break the entities created by the other replacements.
    for raw, safe in (("&", "&amp;"), ("<", "&lt;"), (">", "&gt;"), ('"', "&quot;"), ("'", "&#x27;")):
        text = text.replace(raw, safe)
    return text


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    for i in range(n):
        print(escape_html(data[1 + i]))


main()

